fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap() is safe here
    *arr.iter().min().unwrap()
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    // Since the array is non-empty, unwrap() is safe here
    *arr.iter().max().unwrap()
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    assert!(!arr.is_empty(), "Input array must be non-empty");
    assert!(
        (0..=100).contains(&q),
        "Percentile q must be within the range 0 to 100 inclusive"
    );

    if q == 0 {
        // Return minimum element for 0 percentile
        return vec_min_i8(&arr);
    } else if q == 100 {
        // Return maximum element for 100 percentile
        return vec_max_i8(&arr);
    } else {
        // For any other percentile q in (0, 100),
        // just return any element of arr that satisfies the existence requirements.
        // Since the array is non-empty, ansuring existence of values <= and >= result,
        // returning any element from arr is valid.

        // A natural choice is to return the element at index proportional to q%
        // after sorting, which is a typical percentile definition,
        // but the problem states any element meeting the conditions is acceptable.

        // We'll return the ceil(q * n / 100)th smallest element
        let mut sorted = arr.clone();
        sorted.sort_unstable();

        // Calculate index as ceil((q/100) * len) - 1 to get 0-based index
        // ceil(x) can be done by (x * len + 99)/100 for integer arithmetic
        // but since q is between 1 and 99 inclusive, 
        // use index = ((q as usize * n) + 99) / 100 - 1,
        // or more simply use floor for simplicity here:
        let n = sorted.len();
        let idx = ((q as usize * n) + 99) / 100;
        let idx = idx.saturating_sub(1); // ensure index not negative

        sorted[idx]
    }
}